values
  ('9d4c480d-4f45-4f39-ad91-c4a1efa460b7', 19, 18, 19, 18, 18, 'high', 'Farg''ona va Toshkent ulgurji bozorlari bilan tuzilgan yetkazib berish shartnomalari tasdiqlandi. Yer ijarasi hujjatlari va kredit tarixi tekshirildi — muammo yo''q.', array['Asoschining Quvada qurgan oldingi issiqxonalari joyida ko''rildi', 'Suv tejash har oylik kommunal xarajatni ~70% kamaytiradi', 'Toshkentdagi 2 ta distribyutor bilan oldindan kelishuv bor'], array['Qishki sovuqda qo''shimcha isitish zaxirasi kerak', 'Sovutgichli transport yo''lda ushlanib qolsa, hosil buzilishi mumkin'], true, '6e12f795-69fe-43df-aade-2b0d80214059', '2026-10-24T10:00:00Z'),
  ('e1419726-cc75-4e37-a75a-8219566f2ff7', 19, 20, 18, 19, 18, 'high', 'Ustalarning ishlab chiqarish hajmi tasdiqlangan. Mukofotlar tannarxi aniq hisoblangan, loyiha hunarmandchilikni rivojlantirish dasturiga mos.', array['Asoschi YUNESKO ko''rgazmalarida qatnashgan, tan olingan usta', 'Mahalliy xaridorlar va sayyohlardan barqaror talab bor', 'Marg''ilon ipak ishlab chiqaruvchilaridan to''g''ridan-to''g''ri xarid — vositachi ustamasi yo''q'], array['Tabiiy bo''yoq rangini saqlash uchun xona harorati nazorat qilinishi kerak', 'Sopolni tashish uchun mustahkam qadoq kerak'], true, '6e12f795-69fe-43df-aade-2b0d80214059', '2026-10-18T10:00:00Z'),
  ('6f3e75b3-a961-4c02-a15d-d768311a82dc', 19, 20, 19, 19, 19, 'high', 'Ta''limga ta''siri katta. NNT maqomi tekshirildi, hokimiyat bilan bepul bino bo''yicha shartnoma tasdiqlandi.', array['Inha va Turin universitetlari bitiruvchilaridan iborat ko''ngilli jamoa', 'To''lov yo''qligi sababli har qanday oila farzandi qatnasha oladi', 'Uskunalar 5 yildan ortiq, ko''p guruhlar uchun ishlatiladi'], array['Kavsharlash uchlari, tishli g''ildiraklar kabi sarf materiallarini doim to''ldirish kerak'], true, '6e12f795-69fe-43df-aade-2b0d80214059', '2026-10-20T10:00:00Z'),
  ('34fae723-c786-42f9-af7b-50f70a21ada1', 19, 20, 18, 19, 19, 'high', 'Ilmiy asosi mustahkam, bir daraxt narxi ochiq hisoblangan. Viloyat o''rmon xo''jaligi qo''llab-quvvatlaydi.', array['20 yilda sinalgan, 82% tutish natijasini beradigan usul', 'Mo''ynoq aholisi uchun ish o''rinlari', 'Sun''iy yo''ldosh orqali ochiq tekshiruv'], array['Erta bahordagi issiq kunlarda namlik saqlovchi gel kerak bo''ladi'], true, '6e12f795-69fe-43df-aade-2b0d80214059', '2026-10-15T10:00:00Z'),
  ('ed6cc46b-3d95-4a28-a5eb-8fc7ca9fb538', 19, 19, 19, 18, 18, 'high', 'Navoiy va Buxoroda hosildan keyingi saqlash joyi yetishmasligi tasdiqlangan, daromad har yili takrorlanadi. Kompaniya Navoiy erkin iqtisodiy zonasida to''g''ri ro''yxatdan o''tgan.', array['Muzli akkumulyator tufayli elektr to''lovlari deyarli yo''q', 'Karmana tumanidagi 18 ta uzumzor egasi bilan niyat bayonnomasi imzolangan', 'Mablag'' ko''chmas mulk va uskuna ko''rinishida saqlanadi'], array['Yozgi terim va qishki ta''mirlash oylari orasida daromad o''zgarib turadi'], true, '6e12f795-69fe-43df-aade-2b0d80214059', '2026-10-22T10:00:00Z'),
  ('c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3', 18, 20, 18, 18, 17, 'high', 'Mashhur hunarmandchilik brendi, ustalar mahorati tasdiqlangan. Oshpazlar orasida O''zbekistonda ham, chet elda ham talab yuqori.', array['Markaziy Osiyoda tan olingan, asrlik oilaviy hunar', 'Xomashyoni to''g''ridan-to''g''ri olish bir dona tannarxini 35% kamaytiradi'], array['Har bir tig''ning o''tkirligini alohida tekshirish kerak'], true, '6e12f795-69fe-43df-aade-2b0d80214059', '2026-10-19T10:00:00Z'),
  ('73cf3516-836c-478a-a790-35b6270b9ae2', 19, 19, 19, 19, 18, 'high', 'Ijtimoiy ta''siri yuqori. Viloyat ta''lim boshqarmalari bilan hamkorlik yo''lga qo''yilgan, sinov bosqichida o''quvchilar darslarni oxirigacha o''tgan.', array['O''zbek tilidagi, mahalliy hayotga yaqin kontent — bu bo''shliqni to''ldiradi', 'Bir o''quvchiga yiliga taxminan 7 500 so''m sarflanadi'], array['Maktablarda internet uzilib turgani uchun internetsiz rejim ishonchli bo''lishi kerak'], true, '6e12f795-69fe-43df-aade-2b0d80214059', '2026-10-21T10:00:00Z'),
  ('3107824e-03ea-4634-a63a-a6f273994879', 19, 19, 19, 18, 17, 'high', 'Mahalliy ishlab chiqarish iqtisodi puxta hisoblangan. Bozor yuk tashuvchilari kooperativlaridan talab katta.', array['Asaka avtomobil zavodidan kelgan kuchli muhandislik tajribasi', 'Benzinli mototsiklga nisbatan arzonligi sababli xaridor 7 oyda xarajatini qoplaydi'], array['Batareya yetkazib berish o''zgarib turadi — mahalliy zaxira kerak'], true, '6e12f795-69fe-43df-aade-2b0d80214059', '2026-10-23T10:00:00Z');

-- 866 simulated contributions (they add up to each project's raised_amount)

-- Totals come from the contributions themselves.
update public.projects p
set raised_amount = t.total, backer_count = t.backers
from (select project_id, sum(amount) as total, count(distinct backer_id) as backers
      from public.contributions group by project_id) t
where p.id = t.project_id;

-- Notifications for these inserts would be noise in a fresh demo.
alter table public.project_updates disable trigger notify_new_update;
alter table public.comments disable trigger notify_new_comment;




alter table public.project_updates enable trigger notify_new_update;
alter table public.comments enable trigger notify_new_comment;


commit;
