insert into public.founder_profiles
  (user_id, display_name, role_title, organization, location, bio, experience_years, registration_number, is_verified, verified_at, verified_by)
values
  ('8740db96-93af-407b-a6e6-82e6da721dd0', 'Azizbek Rahimov', 'Asoschi, agronom', '"AgroSmart Farg''ona" MChJ', 'Farg''ona', 'Toshkent davlat agrar universiteti bitiruvchisi. 11 yildan beri O''zbekiston va Turkiyada issiqxona tizimlarini quradi.', 11, 'MChJ guvohnomasi № 309812490 (Farg''ona shahri)', true, '2026-09-15T08:00:00.000Z', '6e12f795-69fe-43df-aade-2b0d80214059'),
  ('7d0a2834-cab2-43b3-a362-4e3793f49478', 'Dilnoza Karimova', 'Kooperativ rahbari, usta to''quvchi', 'Samarqand hunarmandlar uyushmasi', 'Samarqand', '19 yillik tajribaga ega usta to''quvchi. O''zbek amaliy san''atini YUNESKO ko''rgazmalarida namoyish etgan.', 19, 'YaTT guvohnomasi № 419203814 (Samarqand)', true, '2026-09-20T08:00:00.000Z', '6e12f795-69fe-43df-aade-2b0d80214059'),
  ('04ead48c-9f90-4fd1-afd0-1600db4fb74f', 'Jasur Bekmurodov', 'Asoschi, robototexnika o''qituvchisi', '"Kelajak muhandislari" NNT', 'Toshkent', 'Toshkentdagi Inha universiteti bitiruvchisi. 7 yildan beri yoshlar uchun muhandislik olimpiadalari tashkil qiladi.', 7, 'NNT reyestri № 1948203 (Adliya vazirligi)', true, '2026-09-10T08:00:00.000Z', '6e12f795-69fe-43df-aade-2b0d80214059'),
  ('ccd673df-5d87-4db1-ae1c-e9cba10c701b', 'Temur Dauletov', 'Ekolog, loyiha rahbari', '"Orolni yashillashtirish" tashabbusi', 'Nukus', '24 yildan beri Qoraqalpog''iston va Ustyurtda cho''l ekologiyasi va tuproqni tiklash bilan shug''ullanadi.', 24, 'Ilmiy-tadqiqot markazi № 049281', true, '2026-09-01T08:00:00.000Z', '6e12f795-69fe-43df-aade-2b0d80214059'),
  ('6c5a0045-2cc6-41de-abfe-5c41c830650f', 'Bobur Alimov', 'Boshqaruvchi hamkor', '"Zarafshon Green Tech" MChJ', 'Navoiy', 'Qayta tiklanuvchi energiya muhandisi. 14 yildan beri yirik quyosh elektr stansiyalari va sanoat sovutgichlari loyihalarida ishlaydi.', 14, 'MChJ guvohnomasi № 308194821 (Navoiy erkin iqtisodiy zonasi)', true, '2026-09-25T08:00:00.000Z', '6e12f795-69fe-43df-aade-2b0d80214059'),
  ('c900dbcb-3572-4692-a8be-fd4af0ced06d', 'Mansur Po''latov', 'Usta pichoqchi, uyushma oqsoqoli', 'Chust pichoqchilar uyushmasi', 'Chust, Namangan viloyati', 'Beshinchi avlod Chust pichoqchisi. Ishlari O''zbekiston davlat tarix muzeyida saqlanadi.', 28, 'YaTT guvohnomasi № 920194812 (Namangan)', true, '2026-09-18T08:00:00.000Z', '6e12f795-69fe-43df-aade-2b0d80214059'),
  ('892102a8-5a9e-42b7-a542-c4200755a6a3', 'Shahnoza Qosimova', 'O''quv dasturi rahbari', '"Registon raqamli" jamg''armasi', 'Samarqand', 'Xalqaro matematika olimpiadasi sovrindorlarining murabbiyi, 12 yillik tajribaga ega pedagog.', 12, 'NNT № 2049182 (Maktabgacha va maktab ta''limi vazirligi hamkori)', true, '2026-09-12T08:00:00.000Z', '6e12f795-69fe-43df-aade-2b0d80214059'),
  ('86361a3b-797e-4827-a46b-5652b846d9d3', 'Sardor Mirzayev', 'Asoschi, bosh muhandis', '"Andijan Mobility" MChJ', 'Andijon', 'Asakadagi avtomobil zavodida 12 yil ishlab chiqarish va dvigatel sinovlari bilan shug''ullangan.', 12, 'MChJ guvohnomasi № 309482103 (Andijon sanoat zonasi)', true, '2026-09-08T08:00:00.000Z', '6e12f795-69fe-43df-aade-2b0d80214059');
