insert into public.project_translations (project_id, language, title, tagline, summary, story, risks)
values
  ('9d4c480d-4f45-4f39-ad91-c4a1efa460b7', 'uz', 'AgroSmart Farg''ona: quyosh energiyali gidroponik issiqxonalar', 'Quva tumanida suvni 78% kam sarflaydigan issiqxona — Farg''ona va Toshkent bozorlari uchun pomidor va qalampir.', 'Quva tumanida tomga o''rnatilgan quyosh panellari bilan ishlaydigan gidroponik issiqxonalar quramiz. Yer osti suvi 78% kam sarflanadi, pomidor va bolgar qalampiri hosili esa ikki baravar oshadi.', 'Farg''ona vodiysida suv yildan-yilga kamaymoqda, ariq usulida sug''orish esa suvning katta qismini isrof qiladi. Biz Quvadagi tajriba issiqxonamizda ikki mavsum yopiq tsiklli gidroponikani sinab ko''rdik: kimyoviy chiqindi yo''q, suv sarfi to''rt barobar kam.
