values
  ('be7dce6a-4e8d-4b13-ac50-14dd52d408b7', '9d4c480d-4f45-4f39-ad91-c4a1efa460b7', 0, 'Yer tekislash va poydevor', 'Quvadagi yer uchastkasida beton poydevor va drenaj ariqlarini tayyorlash.', '1-oy', 30),
  ('b9571c77-72ae-452b-ad93-0d4931838058', '9d4c480d-4f45-4f39-ad91-c4a1efa460b7', 1, 'Karkas va quyosh panellari', 'Po''lat karkasni o''rnatish, polikarbonat bilan qoplash, panellarni ulash.', '2-oy', 40),
  ('f5f92d7f-2d13-445c-a61d-0b5dc1e0b8d6', '9d4c480d-4f45-4f39-ad91-c4a1efa460b7', 2, 'Sug''orish tizimi va birinchi ekin', 'Tomchilatib sug''orishni o''rnatish, o''g''it sinovi, birinchi ko''chatlarni ekish.', '3-oy', 20),
  ('001387d4-9e9e-46c7-a875-a38aa15bdefa', '9d4c480d-4f45-4f39-ad91-c4a1efa460b7', 3, 'Birinchi hosil va yetkazib berish', 'Toshkentdagi hamkor do''konlarga 12 tonna oliy navli hosil topshirish.', '5-oy', 10),
  ('a481dcef-fcd4-4ebf-a337-a4181a74887c', 'e1419726-cc75-4e37-a75a-8219566f2ff7', 0, 'Ipak xarid qilish va bo''yoq tayyorlash', '140 kg xom ipak olish; yong''oq, ruyan va anor po''stidan bo''yoq tayyorlash.', '1-oy', 35),
  ('63ccfadb-c2a0-4c38-a79e-b84bcc10b121', 'e1419726-cc75-4e37-a75a-8219566f2ff7', 1, 'Pech o''rnatish va sinov', 'Elektr pechni ustaxonaga ulash, kobalt sirni sinab ko''rish.', '2-oy', 35),
  ('6eba2e23-d537-406a-a3b5-f78ca1f7bcf0', 'e1419726-cc75-4e37-a75a-8219566f2ff7', 2, 'Mukofotlarni to''qish va sifat nazorati', 'Barcha ro''mollarni to''qib bo''lish, sopol laganlarga muhr bosish.', '3-oy', 20),
  ('91a8d974-17ee-46c8-af1f-b55a77ef283d', 'e1419726-cc75-4e37-a75a-8219566f2ff7', 3, 'Qadoqlash va yetkazib berish', 'Sug''urtalangan posilkalarni O''zbekiston bo''ylab va chet elga jo''natish.', '4-oy', 10),
  ('f5bfb86f-c511-496a-aa78-799e8783911c', '6f3e75b3-a961-4c02-a15d-d768311a82dc', 0, 'Chilonzordagi xonani ta''mirlash', 'Alohida elektr tarmog''i, kuchlanish himoyasi va antistatik pol yotqizish.', '1-oy', 25),
