  ('d93f52a4-da32-494e-a0cb-581283b13684', '6f3e75b3-a961-4c02-a15d-d768311a82dc', 2, 'Birinchi guruh — 150 o''quvchi', 'Qabulni ochish; o''rinlarning bir qismi davlat maktabi o''quvchilariga.', '3-oy', 20),
  ('90ee27c1-c7bd-4054-a80e-d000f9cabda3', '6f3e75b3-a961-4c02-a15d-d768311a82dc', 3, 'Ochiq kun va ko''rgazma', 'O''quvchilar yasagan issiqxona datchiklari va mini-roverlarni ota-onalarga ko''rsatish.', '5-oy', 10),
  ('3551852a-1b20-457e-a35b-2d4cf60153d4', '34fae723-c786-42f9-af7b-50f70a21ada1', 0, 'Ko''chatlarni chiniqtirish', 'Qo''ng''irot ko''chatxonasida 50 000 ta ikki yillik ko''chatni saralash.', '1-oy', 35),
  ('6bbdaf21-a427-40aa-abd9-201ed41355d4', '34fae723-c786-42f9-af7b-50f70a21ada1', 1, 'Birinchi ekish — 25 000 daraxt', 'Janubiy qismdagi 4B uchastkasiga ekish.', '2-oy', 35),
  ('b352c429-18f7-44d3-a3a6-b648ca95198d', '34fae723-c786-42f9-af7b-50f70a21ada1', 2, 'Ikkinchi ekish — 25 000 daraxt', 'Shimoliy himoya chizig''ini ekib bo''lish.', '3-oy', 20),
  ('83da2a2a-af98-4209-a280-447a08edd583', '34fae723-c786-42f9-af7b-50f70a21ada1', 3, 'Bahorgi sanoq va ochiq hisobot', 'Tutgan daraxtlar xaritasini va homiylar uchun GPS sahifani e''lon qilish.', '6-oy', 10),
  ('9585b15b-41ed-4d17-aaf4-9e845211bd54', 'ed6cc46b-3d95-4a28-a5eb-8fc7ca9fb538', 0, 'Yer ishlari va beton maydon', 'Navoiydagi 1 000 kv. metrlik uchastkani tekislash, armaturali beton quyish.', '1-oy', 30),
