  ('75d5e9fe-631a-4cea-ad1c-9b74e2ee6461', 'ed6cc46b-3d95-4a28-a5eb-8fc7ca9fb538', 3, 'Fermerlardan birinchi hosil', '150 tonnalik omborni Navoiy uzumi va anori bilan to''ldirish.', '4-oy', 10),
  ('596a3d37-84b4-4c0e-a1fc-bf5bc01cfca2', 'c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3', 0, 'Ustaxonani yangilash va press o''rnatish', '25 tonnalik pressni tebranishga chidamli poydevorga o''rnatish.', '1-oy', 40),
  ('6bbcd120-f508-4c35-af85-b65f1bb0164d', 'c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3', 1, 'Damask po''latni toblash', 'Homiylar uchun birinchi 150 ta raqamlangan tig''ni bolg''alash va shakllantirish.', '2-oy', 40),
  ('c5d9838a-e882-4d82-a6c0-a81f27110573', 'c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3', 2, 'Dasta o''rnatish va charxlash', 'Yong''oq dastalarni o''rnatish va tig''ni 14° burchakda charxlash.', '3-oy', 15),
  ('0937df74-08c5-4cae-acf2-3920bef54ceb', 'c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3', 3, 'Homiylarga yetkazib berish', 'Sug''urtalangan qutilarni barcha homiylar manziliga jo''natish.', '4-oy', 5),
  ('78b136d6-4267-433e-a304-73caa842eaaa', '73cf3516-836c-478a-a790-35b6270b9ae2', 0, '5–8-sinflar dasturi tayyor', 'Barcha masalalarni davlat ta''lim standartlariga moslashtirish.', '1-oy', 30),
  ('f1a6b7bc-25d2-4ac8-a4ac-b2466b7e1bc5', '73cf3516-836c-478a-a790-35b6270b9ae2', 1, 'Sinov versiyasi 10 ta maktabda', 'Samarqand tumanidagi 1 200 nafar o''quvchiga ilovani berish.', '2-oy', 40),
  ('c755e49b-5d40-4e84-af44-1132b061562c', '73cf3516-836c-478a-a790-35b6270b9ae2', 2, 'Ovozlashtirish va to''liq ishga tushirish', 'Yuqori sinflar uchun algebra va geometriya bo''limlarini chiqarish.', '3-oy', 20),
  ('5df6d7f2-1dc1-465c-a7e0-738507ba24cc', '73cf3516-836c-478a-a790-35b6270b9ae2', 3, 'Yil yakuni olimpiadasi va natijalar', 'O''quvchilar bilimi qanchalik oshganini homiylarga e''lon qilish.', '6-oy', 10),
  ('00f2c732-b6f0-4dc8-a106-39e1b6993882', '3107824e-03ea-4634-a63a-a6f273994879', 0, 'Yig''uv moslamalarini ishga tushirish', 'Andijondagi sexda rama yig''ish moslamalarini o''rnatish.', '1-oy', 35),
  ('e7979a80-9b1e-43ea-a25d-dfb6e2fb5f0a', '3107824e-03ea-4634-a63a-a6f273994879', 1, 'Birinchi 30 ta mototsikl', '30 ta tijorat mototsiklini yig''ish va stendda sinash.', '2-oy', 35),
  ('bf77bda8-5e6a-4fa5-a3b4-1531cfa3b97e', '3107824e-03ea-4634-a63a-a6f273994879', 2, 'Bozorda sinov', 'Andijon markaziy bozoridagi haydovchilarga 20 ta sinov mototsiklini berish.', '4-oy', 20),
  ('f326469f-552a-423b-aeb4-1bef700b95ca', '3107824e-03ea-4634-a63a-a6f273994879', 3, 'Seriyali ishlab chiqarish', 'Oyiga 50 ta mototsikl ishlab chiqarish va buyurtmalarni bajarish.', '6-oy', 10);
