  ('135e3a9a-73c8-473a-ac31-7c63e401d60a', 'e1419726-cc75-4e37-a75a-8219566f2ff7', 0, 'Samarqand kobalt piyolasi va likopchasi', 'Qo''lda yasalgan, an''anaviy Samarqand naqshli sopol piyola. Usta imzosi bilan.', 350000, array['Sopol piyola', 'Likopcha', 'Kelib chiqish sertifikati'], '2026-yil dekabr', 100, 17),
  ('ef31f3ee-f395-4bfa-aa0c-325aea9a786f', 'e1419726-cc75-4e37-a75a-8219566f2ff7', 1, 'Qo''lda to''qilgan ipak atlas ro''mol (180×50 sm)', 'Tabiiy bo''yoqlar bilan, yog''och dastgohda to''qilgan "bodom" naqshli sof ipak ro''mol.', 850000, array['Sof ipak ro''mol', 'Yog''och sovg''a qutisi', 'Samarqand to''quvchilari haqida kitobcha'], '2027-yil yanvar', 50, 26),
  ('298d61ad-97f5-4a88-a7ce-41e6c6738802', 'e1419726-cc75-4e37-a75a-8219566f2ff7', 2, 'Master-klass va 7 qismli sopol to''plam', 'Osh uchun katta lagan va 6 ta piyola, hamda Samarqanddagi ustaxonada yarim kunlik shaxsiy mashg''ulot.', 2500000, array['Katta lagan (38 sm)', '6 ta piyola', '4 soatlik master-klass', 'Uyushmada umrbod 15% chegirma'], '2027-yil yanvar', 20, 0),
  ('8297f50b-72e1-4a9f-aa86-606527beda91', 'c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3', 0, 'An''anaviy Chust pichog''i (12 sm)', 'Jilolangan jez va suyak dastali, charx toshida qo''lda o''tkirlangan 12 sm li pichoq.', 280000, array['Chust pichog''i', 'Bo''rtma naqshli charm g''ilof', 'Charx tosh'], '2026-yil dekabr', 60, 23),
  ('20864980-7dad-4fe0-a7c2-73bbc3901554', 'c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3', 1, 'Osh pichog''i, katta (22 sm)', '67 qatlamli damask tig'' va Farg''ona yong''og''idan dasta. Osh tayyorlash va go''sht uchun.', 650000, array['Katta Chust pichog''i', 'Yog''och sovg''a qutisi', 'Haqiqiylik sertifikati'], '2027-yil yanvar', 75, 15);
