insert into public.project_updates (id, project_id, author_id, title, body, created_at)
values
  ('89e08185-355a-4cc7-a12c-510589d0f213', '9d4c480d-4f45-4f39-ad91-c4a1efa460b7', '8740db96-93af-407b-a6e6-82e6da721dd0', 'Poydevor tayyor, quyosh panellari yetib keldi', 'Quvadagi poydevor to''liq qotdi. Kecha texnik guruhimiz quyosh panellari va invertorlarni tekshirdi — barcha elektr sinovlaridan o''tdi.', '2026-10-28T12:00:00Z'),
  ('84c2ebdc-654b-4950-ac7f-8f08cb00e3c5', 'e1419726-cc75-4e37-a75a-8219566f2ff7', '7d0a2834-cab2-43b3-a362-4e3793f49478', 'Elektr pechda birinchi sinov — birorta nuqsonsiz', 'Kecha kulol ustamiz Mahmud aka 1 180°C dagi birinchi kuydirishdan keyin pech eshigini ochdi. Laganlardagi kobalt rang juda yorqin chiqdi.', '2026-10-26T12:00:00Z'),
  ('920bb183-49ad-486c-a80e-126d85ccf54b', '6f3e75b3-a961-4c02-a15d-d768311a82dc', '04ead48c-9f90-4fd1-afd0-1600db4fb74f', 'Antistatik pol yotqizildi, 20 ta stol keldi', 'Sizning yordamingiz bilan Chilonzordagi xona haqiqiy laboratoriyaga aylandi! ESP32 va Arduino platalarining birinchi partiyasi bojxonadan kechikmasdan o''tdi.', '2026-10-31T12:00:00Z'),
  ('01dc493b-8eb3-45f4-a0f5-791f1318a142', '34fae723-c786-42f9-af7b-50f70a21ada1', 'ccd673df-5d87-4db1-ae1c-e9cba10c701b', '4B uchastkasiga 25 000 ko''chat ekildi!', 'Jamoamiz sovuq cho''l shamoliga qaramay janubiy uchastkani muddatidan oldin ekib bo''ldi. Oktabr yomg''irlaridan keyin tuproq namligi aynan kerakli darajada.', '2026-10-25T12:00:00Z'),
  ('c942a2c9-09fa-4641-a846-60bb525f3e84', 'ed6cc46b-3d95-4a28-a5eb-8fc7ca9fb538', '6c5a0045-2cc6-41de-abfe-5c41c830650f', 'Karmanada sovutgich kamera devorlari tayyor', '150 mm qalinlikdagi kamera devorlari germetik yopildi. Keyingi hafta tomga 45 kVt quyosh panellari o''rnatiladi.', '2026-10-29T12:00:00Z'),
  ('595eca64-a1f1-4624-a4d5-e6293711a62f', 'c425ad3b-ebfc-49d6-a8a7-d237cc54b3c3', 'c900dbcb-3572-4692-a8be-fd4af0ced06d', 'Birinchi 50 ta damask zagotovka tayyor — naqshi patday', 'Mansur usta birinchi partiyani toblab bo''ldi. Nikelli va uglerodli qatlamlar orasidagi naqsh juda chiroyli chiqdi.', '2026-10-27T12:00:00Z'),
  ('43234a23-cdd2-482e-abdd-52059f5764bd', '73cf3516-836c-478a-a790-35b6270b9ae2', '892102a8-5a9e-42b7-a542-c4200755a6a3', '7-sinf geometriyasi bo''yicha interaktiv darslar sinovga chiqdi', 'Endi o''quvchilar 3D shakllarni ekranda aylantirib ko''ra oladi, hamma narsa o''zbek tilida ovozli tushuntiriladi.', '2026-10-30T12:00:00Z'),
  ('b0548cce-9d05-48ec-ad6c-29f10d1a4bf3', '3107824e-03ea-4634-a63a-a6f273994879', '86361a3b-797e-4827-a46b-5652b846d9d3', 'Rama 1 000 kg yuk sinovidan o''tdi', 'Mustahkamlangan rama ruxsat etilgan yukdan 1,5 baravar og''ir yuk ostida ham egilmadi. Batareya mahkamlagichlari sertifikatlandi.', '2026-10-29T12:00:00Z');
