insert into public.comments (id, project_id, author_id, parent_id, body, created_at)
values
  ('c34f5a57-adbb-4716-a157-c8c9a4b0a444', '9d4c480d-4f45-4f39-ad91-c4a1efa460b7', '4f389dab-f00b-4f5d-a11b-523b377a7fd9', null, 'Poydevor ishlari zo''r ketyapti. Choraklik foyda qachon to''lanadi?', '2026-10-29T14:00:00Z'),
  ('806a0fe3-7c08-4737-ad41-efab6bafda9d', '9d4c480d-4f45-4f39-ad91-c4a1efa460b7', '8740db96-93af-407b-a6e6-82e6da721dd0', 'c34f5a57-adbb-4716-a157-c8c9a4b0a444', 'Assalomu alaykum, Farrux! Har chorak yopilgandan keyin 15 kun ichida, tekshirilgan savdo hisoboti bilan birga to''lanadi.', '2026-10-30T16:00:00Z'),
  ('c1c1adcb-4ab7-4708-a464-14291fd74e7a', 'e1419726-cc75-4e37-a75a-8219566f2ff7', 'd248589e-f899-441c-ad32-e47beb051161', null, 'Ustalarimizni qo''llab-quvvatlaganimdan xursandman! Ro''mol uchun homiy bo''lsak, ustaxonaga borsak bo''ladimi?', '2026-10-27T14:00:00Z'),
  ('82d83034-083c-4ff6-aab3-e10af2b9bbf6', 'e1419726-cc75-4e37-a75a-8219566f2ff7', '7d0a2834-cab2-43b3-a362-4e3793f49478', 'c1c1adcb-4ab7-4708-a464-14291fd74e7a', 'Albatta, Gulnora opa! Samarqandga kelganingizda barcha homiylarni choy va shirinlik bilan kutib olamiz.', '2026-10-28T16:00:00Z'),
  ('8195e566-1886-4a21-afa3-3c016502b04b', '6f3e75b3-a961-4c02-a15d-d768311a82dc', '246bfaef-64d8-42e0-ae06-2dece0ef30a5', null, '12 yoshli qizim mashg''ulotlar boshlanishini intiqlik bilan kutyapti! Qo''llab-quvvatlaganimdan faxrlanaman.', '2026-11-01T14:00:00Z'),
  ('fd8537e1-40df-4abd-a78f-953a6476745d', '34fae723-c786-42f9-af7b-50f70a21ada1', '2e0531a3-1f4e-4f68-a6cf-648f31fd4575', null, 'Orol — hammamizning mas''uliyatimiz. Temur aka, umringizni shu ishga bag''ishlaganingiz uchun rahmat.', '2026-10-27T14:00:00Z'),
  ('592a5233-dee6-49d3-a9c3-1006241e3ea7', 'ed6cc46b-3d95-4a28-a5eb-8fc7ca9fb538', 'd6dba0b1-7df4-461a-a261-b82d006b5515', null, '15 mln so''m (demo) bilan qo''shildim. Toza texnologiya fermerlarning haqiqiy muammosini hal qilayotgani yoqdi.', '2026-10-30T14:00:00Z');
